// Get the canvas element from the DOM
const canvas = document.querySelector("#scene");
if (!canvas || !canvas.getContext) {
  console.error("Canvas not supported or not found");
} else {
  const ctx = canvas.getContext("2d");

  // Set up canvas dimensions based on device pixel ratio
  function setCanvasSize() {
    canvas.width = canvas.clientWidth * (window.devicePixelRatio || 1);
    canvas.height = canvas.clientHeight * (window.devicePixelRatio || 1);
    ctx.scale(window.devicePixelRatio || 1, window.devicePixelRatio || 1);
  }
  setCanvasSize();

  // Configuration constants
  const config = {
    totalDots: 1000, // Number of dots
    dotSize: 4, // Size of each dot
    globeRadiusFactor: 0.7, // Proportion of canvas width
    perspectiveFactor: 0.8, // Perspective field of view factor
  };

  // Variables
  let canvasWidth = canvas.clientWidth;
  let canvasHeight = canvas.clientHeight;
  let rotationAngle = 0; // Rotation of the globe
  let dotsArray = []; // Array to hold dots
  let globeRadius = canvasWidth * config.globeRadiusFactor;
  let globeCenterZ = -globeRadius; // Z-axis position of the globe's center
  let canvasCenterX = canvasWidth / 2; // X center of the canvas
  let canvasCenterY = canvasHeight / 2; // Y center of the canvas
  let perspectiveDepth = canvasWidth * config.perspectiveFactor;

  // DOT FUNCTIONS
  function createDot(x, y, z) {
    // Define the dot's 3D coordinates and projected values
    const dot = {
      x,
      y,
      z,
      xProjected: 0,
      yProjected: 0,
      sizeProjected: 0,
    };

    // Project 3D coordinates into 2D space
    function project(sinAngle, cosAngle) {
      const rotatedX = cosAngle * dot.x + sinAngle * (dot.z - globeCenterZ);
      const rotatedZ =
        -sinAngle * dot.x + cosAngle * (dot.z - globeCenterZ) + globeCenterZ;
      const scaleFactor = perspectiveDepth / (perspectiveDepth - rotatedZ);

      dot.xProjected = rotatedX * scaleFactor + canvasCenterX;
      dot.yProjected = dot.y * scaleFactor + canvasCenterY;
      dot.sizeProjected = config.dotSize * scaleFactor;
    }

    return {
      project,
      getProjected: () => dot, // Expose the dot's projected properties
    };
  }

  // Create dots and position them on the globe
  function initializeDots() {
    dotsArray = [];
    for (let i = 0; i < config.totalDots; i++) {
      const theta = Math.random() * 2 * Math.PI; // Angle around the globe
      const phi = Math.acos(Math.random() * 2 - 1); // Latitude on the globe

      const x = globeRadius * Math.sin(phi) * Math.cos(theta);
      const y = globeRadius * Math.sin(phi) * Math.sin(theta);
      const z = globeRadius * Math.cos(phi) + globeCenterZ;

      dotsArray.push(createDot(x, y, z));
    }
  }

  // RENDER
  function renderScene(timestamp) {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update rotation angle
    rotationAngle = timestamp * 0.0004; // Adjustable rotation speed
    const sinAngle = Math.sin(rotationAngle);
    const cosAngle = Math.cos(rotationAngle);

    // Batch draw all dots for performance
    ctx.fillStyle = "#ffffff"; // White dots for visibility
    ctx.beginPath();
    dotsArray.forEach((dot) => {
      dot.project(sinAngle, cosAngle);
      const projected = dot.getProjected();
      ctx.moveTo(projected.xProjected, projected.yProjected);
      ctx.arc(projected.xProjected, projected.yProjected, projected.sizeProjected, 0, Math.PI * 2);
    });
    ctx.fill();

    window.requestAnimationFrame(renderScene);
  }

  // RESIZE EVENT
  function onResize() {
    setCanvasSize();
    canvasWidth = canvas.clientWidth;
    canvasHeight = canvas.clientHeight;
    globeRadius = canvasWidth * config.globeRadiusFactor;
    globeCenterZ = -globeRadius;
    canvasCenterX = canvasWidth / 2;
    canvasCenterY = canvasHeight / 2;
    perspectiveDepth = canvasWidth * config.perspectiveFactor;

    initializeDots(); // Recreate dots after resizing
  }

  window.addEventListener("resize", onResize);

  // Initialize and start the scene
  initializeDots();
  window.requestAnimationFrame(renderScene);
}
